"use strict";
const{test}=require("node:test"),S=require("./support.cjs"),{assert}=S;
test("managed factory is actual HubDataStore without legacy initialization",async t=>{const f=await S.fixture(t);assert(f.store instanceof S.api.HubDataStore);assert.equal(f.store.plugin,undefined);assert.equal(f.store.deviceId,undefined);assert.equal(f.store.sharedProjects,undefined);});
test("disjoint stale requests preserve both scoped changes and excluded logical data",async t=>{const f=await S.fixture(t),r=await S.read(f),a=S.request(f,r,{workspaceMode:{value:1}}),b=S.request(f,r,{folderUi:{value:2}});const results=await Promise.all([f.store.transact(a),f.store.transact(b)]);assert.deepEqual(results.map(x=>x.status),["committed","committed"]);const d=await S.disk(f);assert.equal(d.data.workspaceMode.value,1);assert.equal(d.data.folderUi.value,2);assert.deepEqual(d.data.categories,[{id:"private-seed"}]);assert.equal(d.data.taskMetadata.sentinel,"preserve");assert.equal(d.data.unrelated.private,"keep");assert.equal(d.revision,2);});
test("same field, presence changes and explicit deletion conflict without publication",async t=>{const f=await S.fixture(t),r=await S.read(f),a=S.request(f,r),b=S.request(f,r);assert.equal((await f.store.transact(a)).status,"committed");assert.equal((await f.store.transact(b)).code,"FIELD_CONFLICT");const current=await S.read(f),del=S.request(f,current);delete del.changes[0].value;del.changes[0].operation="delete";assert.equal((await f.store.transact(del)).status,"committed");assert.equal((await f.store.transact(S.request(f,current))).status,"conflict");const absent=await S.read(f);assert.equal(absent.fields[0].present,false);assert.equal((await f.store.transact(S.request(f,absent))).status,"committed");});
test("multi-field replace is one revision and one receipt",async t=>{const f=await S.fixture(t),r=await S.read(f),q=S.request(f,r,{workspaceMode:{a:1},folderUi:{b:2}}),out=await f.store.transact(q);assert.equal(out.status,"committed");assert.equal(out.result.selected.length,2);assert.equal((await S.disk(f)).receipts.length,1);});
test("declared dependencies require original guards and reject a changed dependency",async t=>{const f=await S.fixture(t,{allowedScopes:[{field:"workspaceMode",dependencies:["folderUi"]},{field:"folderUi",dependencies:[]}]}),r=await S.read(f,["workspaceMode","folderUi"]);assert.equal((await f.store.transact(S.request(f,r))).code,"DEPENDENCY_REQUIRED");await f.store.transact(S.request(f,r,{folderUi:{changed:true}}));assert.equal((await f.store.transact(S.request(f,r,{workspaceMode:{x:1}},undefined,["folderUi"]))).status,"conflict");});
test("read results and caller drafts are detached across pending mutation",async t=>{const f=await S.fixture(t),r=await S.read(f),q=S.request(f,r);const pending=f.store.transact(q);q.changes[0].value.value=99;r.fields[0].value.value=88;assert.equal((await pending).status,"committed");assert.equal((await S.disk(f)).data.workspaceMode.value,1);});
for(const field of ["categories","projectPlanning","taskMetadata","headerImagePlacements","hubState","receipts","unknown"]){test("reserved or excluded scope: "+field,async t=>{const f=await S.fixture(t),r=await S.read(f),q=S.request(f,r);q.changes[0].field=field;await assert.rejects(async()=>f.store.transact(q),{code:"APPLICATION_CONTRACT"});assert.equal((await S.disk(f)).revision,0);});}
for(const mutation of [q=>q.extra=true,q=>q.changes.push(q.changes[0]),q=>q.changes[0].value=NaN,q=>q.observation.snapshotDigest="bad",q=>q.changes[0].operation="append",q=>q.changes[0].value=()=>{},q=>q.changes[0].value=Object.defineProperty({},"x",{get(){throw Error("getter executed");},enumerable:true})])test("malformed original request rejects before publication "+mutation.toString(),async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));mutation(q);await assert.rejects(async()=>f.store.transact(q));assert.equal((await S.disk(f)).revision,0);});
test("forged original observation cannot become a new request",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));q.observation.snapshotDigest="a".repeat(64);assert.equal((await f.store.transact(q)).code,"OBSERVATION_INVALID");});
test("cancellation before publication creates no receipt",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));assert.equal((await f.store.transact(q,AbortSignal.abort())).status,"cancelled");assert.equal((await S.disk(f)).revision,0);});
test("canonical mechanics match the existing portable-value contract",()=>{const V=require(S.path.resolve(__dirname,"../../../../../../ItacanTaskCore/src/value"));for(const value of [{z:-0,a:[null,{"10":1,"2":2,b:"😀\u0000"}]},[],null,{a:1e-324}])assert.equal(S.C.canonical(value),V.canonical(value));for(const value of [NaN,Infinity,undefined,new Date(),[,1],JSON.parse('{"__proto__":1}')]){assert.throws(()=>S.C.canonical(value));assert.throws(()=>V.canonical(value));}});

test("replacement top-level shape is validated without legacy coercion",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));q.changes[0].value=123;await assert.rejects(async()=>f.store.transact(q),{code:"APPLICATION_CONTRACT"});assert.equal((await S.disk(f)).revision,0);});
test("a declared dependency succeeds when its exact original value remains valid",async t=>{const f=await S.fixture(t,{allowedScopes:[{field:'workspaceMode',dependencies:['folderUi']},{field:'folderUi',dependencies:[]}]}),r=await S.read(f,['workspaceMode','folderUi']),q=S.request(f,r,{workspaceMode:{a:1}},undefined,['folderUi']);assert.equal((await f.store.transact(q)).status,'committed');});
